arguments.file_text:
@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = Catalog.SearchCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Availability</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    var dept = Catalog.GetDepartment(course.DepartmentId);
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                    <tr>
                        <td><strong>@course.CourseCode</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>
                            @if (spotsLeft > 10)
                            {
                                <span class="badge bg-success">@spotsLeft spots</span>
                            }
                            else if (spotsLeft > 0)
                            {
                                <span class="badge bg-warning text-dark">@spotsLeft spots</span>
                            }
                            else
                            {
                                <span class="badge bg-danger">Full</span>
                            }
                        </td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="courses" class="btn btn-secondary">Back to Catalog</a>
}
else
{
    <PageTitle>@course.CourseCode — @course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="courses?departmentId=@dept!.Id">@dept.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.CourseCode — @course.Title</h1>
            <p class="lead">@course.Description</p>

            <h3 class="mt-4">Schedule &amp; Location</h3>
            <table class="table">
                <tbody>
                    <tr><th scope="row" style="width:150px;">Schedule</th><td>@course.Schedule</td></tr>
                    <tr><th scope="row">Location</th><td>@course.Location</td></tr>
                    <tr><th scope="row">Credits</th><td>@course.Credits</td></tr>
                    <tr>
                        <th scope="row">Enrollment</th>
                        <td>
                            @course.CurrentEnrollment / @course.MaxEnrollment
                            @{ var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment; }
                            @if (spotsLeft > 10)
                            {
                                <span class="badge bg-success ms-2">@spotsLeft spots available</span>
                            }
                            else if (spotsLeft > 0)
                            {
                                <span class="badge bg-warning text-dark ms-2">@spotsLeft spots left</span>
                            }
                            else
                            {
                                <span class="badge bg-danger ms-2">Full</span>
                            }
                        </td>
                    </tr>
                </tbody>
            </table>

            <div class="mt-3">
                <a href="enroll?courseId=@course.Id" class="btn btn-primary">Request Enrollment</a>
                <a href="courses" class="btn btn-outline-secondary ms-2">Back to Catalog</a>
            </div>
        </div>

        <div class="col-lg-4">
            @if (instructor is not null)
            {
                <div class="card mt-4 mt-lg-0">
                    <div class="card-body">
                        <h4 class="card-title">Instructor</h4>
                        <h5>@instructor.Name</h5>
