@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var courses = Catalog.SearchCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Availability</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    var dept = Catalog.GetDepartment(course.DepartmentId);
                    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                    <tr>
                        <td><strong>@course.CourseCode</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>
                            @if (spotsLeft > 10)
                            {
                                <span class="badge bg-success">@spotsLeft spots</span>
                            }
                            else if (spotsLeft > 0)
                            {
                                <span class="badge bg-warning text-dark">@spotsLeft spots</span>
                            }
                            else
                            {
                                <span class="badge bg-danger">Full</span>
                            }
                        </td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="courses" class="btn btn-secondary">Back to Catalog</a>
}
else
{
    <PageTitle>@course.CourseCode — @course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="courses?departmentId=@dept!.Id">@dept.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.CourseCode — @course.Title</h1>
            <p class="lead">@course.Description</p>

            <h3 class="mt-4">Schedule &amp; Location</h3>
            <table class="table">
                <tbody>
                    <tr><th scope="row" style="width:150px;">Schedule</th><td>@course.Schedule</td></tr>
                    <tr><th scope="row">Location</th><td>@course.Location</td></tr>
                    <tr><th scope="row">Credits</th><td>@course.Credits</td></tr>
                    <tr>
                        <th scope="row">Enrollment</th>
                        <td>
                            @course.CurrentEnrollment / @course.MaxEnrollment
                            @{ var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment; }
                            @if (spotsLeft > 10)
                            {
                                <span class="badge bg-success ms-2">@spotsLeft spots available</span>
                            }
                            else if (spotsLeft > 0)
                            {
                                <span class="badge bg-warning text-dark ms-2">@spotsLeft spots left</span>
                            }
                            else
                            {
                                <span class="badge bg-danger ms-2">Full</span>
                            }
                        </td>
                    </tr>
                </tbody>
            </table>

            <div class="mt-3">
                <a href="enroll?courseId=@course.Id" class="btn btn-primary">Request Enrollment</a>
                <a href="courses" class="btn btn-outline-secondary ms-2">Back to Catalog</a>
            </div>
        </div>

        <div class="col-lg-4">
            @if (instructor is not null)
            {
                <div class="card mt-4 mt-lg-0">
                    <div class="card-body">
                        <h4 class="card-title">Instructor</h4>
                        <h5>@instructor.Name</h5>
                        <p class="text-muted mb-2">@instructor.Title</p>
                        <p>@instructor.Bio</p>
                        <p class="mb-0"><strong>Email:</strong> <a href="mailto:@instructor.Email">@instructor.Email</a></p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;
    private Department? dept;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            dept = Catalog.GetDepartment(course.DepartmentId);
            instructor = Catalog.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@inject EnrollmentService Enrollment
@inject NavigationManager Nav

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive confirmation from the registrar's office.</p>

<div class="row">
    <div class="col-lg-8">
        <EditForm Model="Model" FormName="EnrollmentForm" OnValidSubmit="HandleSubmit" method="post">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                <ValidationMessage For="() => Model.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU12345" />
                <ValidationMessage For="() => Model.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in Catalog.GetAllCourses())
                    {
                        var dept = Catalog.GetDepartment(course.DepartmentId);
                        <option value="@course.Id">@course.CourseCode — @course.Title (@dept?.Code)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="notes" class="form-label">Additional Notes (optional)</label>
                <InputTextArea id="notes" @bind-Value="Model.Notes" class="form-control" rows="3" />
                <ValidationMessage For="() => Model.Notes" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Request</button>
            <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Enrollment.Submit(Model);
        Nav.NavigateTo($"enroll/confirmation?courseId={Model.CourseId}&studentName={Uri.EscapeDataString(Model.StudentName)}");
    }
}

@page "/enroll/confirmation"
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request Submitted</PageTitle>

<div class="text-center py-5">
    <h1 class="text-success">✓ Request Submitted</h1>
    <p class="lead mt-3">
        Thank you, <strong>@StudentName</strong>! Your enrollment request
        @if (course is not null)
        {
            <text> for <strong>@course.CourseCode — @course.Title</strong></text>
        }
        has been submitted successfully.
    </p>
    <p>The registrar's office will review your request and send a confirmation to your university email.</p>

    <div class="mt-4">
        <a href="courses" class="btn btn-primary me-2">Browse More Courses</a>
        <a href="enroll" class="btn btn-outline-secondary">Submit Another Request</a>
    </div>
</div>

@code {
    [SupplyParameterFromQuery] public string? StudentName { get; set; }
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue)
            course = Catalog.GetCourse(CourseId.Value);
    }
}

